sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    try {
        var newTradeTaskSysId = '';
        var newTradeCaseSysId = '';
        var newTradeSysId = '';
        var newTradeCount = '';
        var parent = new GlideRecord('x_hsb11_mss_smh_parent_aggregated_trade_chat_queue');
        var child = new GlideRecord('x_hsb11_mss_smh_child_aggregated_trade_chat_queue');
        child.addQuery('trade_case', current.sys_id);
        child.query();
        while (child.next()) {
            if (child.symphony_response == '') {
                child.symphony_response = 'Exception resolved';
                child.symphony_response_by = 'System';
                child.actioned = 'true';
                child.update();
            }
            var brother = new GlideRecord('x_hsb11_mss_smh_child_aggregated_trade_chat_queue');
            brother.addQuery('parent', child.parent);
            brother.addQuery('actioned', 'false');
            brother.query();
            if (brother.next()) {
                newTradeTaskSysId = brother.getValue('trade_case_task');
                newTradeCaseSysId = brother.getValue('trade_case');
                newTradeSysId = brother.trade_case_task.financial_object;
            }
            parent = new GlideRecord('x_hsb11_mss_smh_parent_aggregated_trade_chat_queue');
            if (parent.get(child.parent)) {
                var tradeTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
                tradeTask.addQuery('parent', current.sys_id);
                tradeTask.query();
                while (tradeTask.next()) {
                    if (tradeTask.getValue('sys_id') == parent.getValue('trade_task_reference')) {
                        var outbound = new GlideRecord('x_hsb11_mss_sw_hsbc_outbound_symphony_message_log');
                        outbound.addQuery('servicenow_task_id', parent.getValue('trade_task_reference'));
                        outbound.query();
                        while (outbound.next()) {
                            if (newTradeTaskSysId != '') {
                                outbound.servicenow_task_id = newTradeTaskSysId;
                                outbound.update();
                            }
                        }
                        var symphonyLog = new GlideRecord('x_hsb11_mss_smh_hsbc_symphony_message_log');
                        symphonyLog.addQuery('servicenow_task_id', parent.getValue('trade_task_reference'));
                        symphonyLog.query();
                        while (symphonyLog.next()) {
                            if (newTradeTaskSysId != '') {
                                symphonyLog.servicenow_task_id = newTradeTaskSysId;
                                symphonyLog.update();
                            }
                        }
                        if (newTradeTaskSysId != '') {
                            parent.trade_task_reference = newTradeTaskSysId;
                            parent.update();
                        }
                        tradeTask.state = current.state;
                        tradeTask.update();
                    } else {
                        tradeTask.state = current.state;
                        tradeTask.update();
                    }
                }
                if (child.parent.aggregation_status == 'Draft') {
                    newTradeCount = child.parent.trade_count - 1;
                    child.parent = '';
                    child.update();
                }
                if (parent.trade_count != newTradeCount && newTradeCount != '') {
                    parent.trade_count = newTradeCount;
                    parent.update();
                }

            } else {
                gs.error('[BR][HSBC-Trade case and task state updation]: Parent not found');
            }
        }
        if (parent) {
            if (parent.trade_count > 1 && parent.aggregation_status == 'Sent') {
                parent.aggregation_status = 'Reponse received';
                parent.update();
            }
        }

		tradeTask = new GlideRecord('x_hsb11_hsbc_mss_t_trade_task');
		tradeTask.addQuery('parent', current.sys_id);
		tradeTask.query();
		while(tradeTask.next()){
			tradeTask.state = current.state;
			tradeTask.update();
		}

    } catch (e) {
        gs.error('[BR][HSBC-Trade case and task state updation]: ' + e.getMessage());
    }
})(current, previous);
